CREATE TABLE users(id BIGSERIAL PRIMARY KEY,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,email_verified BOOLEAN NOT NULL DEFAULT FALSE,account_non_locked BOOLEAN NOT NULL DEFAULT TRUE,mfa_enabled BOOLEAN NOT NULL DEFAULT FALSE,failed_login_attempts INTEGER NOT NULL DEFAULT 0,locked_until TIMESTAMPTZ,mfa_secret VARCHAR(255));
CREATE TABLE roles(id BIGSERIAL PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,description VARCHAR(255));
CREATE TABLE permissions(id BIGSERIAL PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,description VARCHAR(255));
CREATE TABLE user_roles(user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,role_id BIGINT REFERENCES roles(id) ON DELETE CASCADE,PRIMARY KEY(user_id,role_id));
CREATE TABLE role_permissions(role_id BIGINT REFERENCES roles(id) ON DELETE CASCADE,permission_id BIGINT REFERENCES permissions(id) ON DELETE CASCADE,PRIMARY KEY(role_id,permission_id));
CREATE TABLE one_time_tokens(id BIGSERIAL PRIMARY KEY,token VARCHAR(255) NOT NULL UNIQUE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL,purpose VARCHAR(20) NOT NULL);
CREATE TABLE refresh_sessions(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash VARCHAR(64) NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,user_agent VARCHAR(255),ip_address VARCHAR(100));
CREATE TABLE audit_logs(id BIGSERIAL PRIMARY KEY,actor_user_id BIGINT,action VARCHAR(100) NOT NULL,target VARCHAR(190),details VARCHAR(1000),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
